CREATE TRIGGER board_message_counts_ad AFTER DELETE ON board_messages BEGIN
	UPDATE board_message_counts SET n = n - 1 WHERE project = OLD.project;
	DELETE FROM board_message_counts WHERE project = OLD.project AND n <= 0;
END

CREATE TRIGGER board_message_counts_ai AFTER INSERT ON board_messages BEGIN
	INSERT INTO board_message_counts (project, n) VALUES (NEW.project, 1) ON CONFLICT (project) DO UPDATE SET n = n + 1;
END

CREATE TRIGGER board_message_counts_au AFTER UPDATE OF project ON board_messages WHEN OLD.project IS NOT NEW.project BEGIN
	UPDATE board_message_counts SET n = n - 1 WHERE project = OLD.project;
	DELETE FROM board_message_counts WHERE project = OLD.project AND n <= 0;
	INSERT INTO board_message_counts (project, n) VALUES (NEW.project, 1) ON CONFLICT (project) DO UPDATE SET n = n + 1;
END
